SELECT COUNT(*)
FROM conversation_analysis
WHERE user_id = #{userId}

SELECT COUNT(*)
FROM conversation_analysis
WHERE user_id = #{userId}

    AND status = #{status}


    AND created_at >= DATE_SUB(NOW(), INTERVAL #{days} DAY)

SELECT id, user_id, analysis_id, conversation_content, status, error_message, processing_time_ms,
educational_summary, llm_model_id, llm_model_name, llm_provider, point_dictionary_version,
edit_annotations, created_at, updated_at
FROM conversation_analysis

    user_id = #{userId}

        AND status = #{status}


        AND created_at >= #{startTime}


        AND created_at <= #{endTime}


        AND conversation_content LIKE CONCAT('%', #{keyword}, '%')


ORDER BY created_at DESC

